tickets = list_tickets('open')
high_customers = []
for tid in tickets:
    t = get_ticket(tid)
    if t['priority'] == 'high':
        cid = t['customer_id']
        if cid not in high_customers:
            high_customers.append(cid)
gold_customers = []
for cid in high_customers:
    c = get_customer(cid)
    if c['tier'] == 'gold':
        gold_customers.append(cid)
count = 0
for cid in gold_customers:
    r = send_message(cid, 'We are on it.')
    if r['ok']:
        count = count + 1
print(count)

